import { test, expect } from '@playwright/test';

test.describe('Change Password from Profile Settings', () => {
  const testUser = {
    email: 'testuser@example.com',
    currentPassword: 'CurrentPassword123!',
    newPassword: 'NewPassword456!',
    confirmPassword: 'NewPassword456!'
  };

  test.beforeEach(async ({ page }) => {
    // Navigate to login page
    await page.goto('/login');

    // Login with test user
    await page.getByLabel('Email').fill(testUser.email);
    await page.getByLabel('Password').fill(testUser.currentPassword);
    await page.getByRole('button', { name: /sign in|login/i }).click();

    // Wait for navigation to dashboard
    await page.waitForURL(/dashboard|home/);

    // Navigate to profile settings
    await page.getByRole('button', { name: /profile|account/i }).click();
    await page.getByRole('link', { name: /settings|preferences/i }).click();

    // Wait for settings page to load
    await page.waitForURL(/settings|profile/);
  });

  test('should successfully change password with valid credentials', async ({ page }) => {
    // Click on change password section
    await page.getByRole('button', { name: /change password|update password/i }).click();

    // Verify change password form is visible
    const passwordForm = page.getByRole('region', { name: /password/i });
    await expect(passwordForm).toBeVisible();

    // Fill in current password
    await page.getByLabel(/current password|existing password/i).fill(testUser.currentPassword);

    // Fill in new password
    await page.getByLabel(/new password/i).first().fill(testUser.newPassword);

    // Fill in confirm password
    await page.getByLabel(/confirm password|repeat password/i).fill(testUser.confirmPassword);

    // Submit the form
    await page.getByRole('button', { name: /save|update|change password/i }).click();

    // Verify success message
    const successMessage = page.getByText(/password.*changed|password.*updated|successfully/i);
    await expect(successMessage).toBeVisible();

    // Verify user is still on settings page
    await expect(page).toHaveURL(/settings|profile/);
  });

  test('should show error when current password is incorrect', async ({ page }) => {
    // Click on change password section
    await page.getByRole('button', { name: /change password|update password/i }).click();

    // Fill in incorrect current password
    await page.getByLabel(/current password|existing password/i).fill('WrongPassword123!');

    // Fill in new password
    await page.getByLabel(/new password/i).first().fill(testUser.newPassword);

    // Fill in confirm password
    await page.getByLabel(/confirm password|repeat password/i).fill(testUser.confirmPassword);

    // Submit the form
    await page.getByRole('button', { name: /save|update|change password/i }).click();

    // Verify error message
    const errorMessage = page.getByText(/incorrect|invalid|wrong.*password/i);
    await expect(errorMessage).toBeVisible();

    // Verify form is still visible
    const passwordForm = page.getByRole('region', { name: /password/i });
    await expect(passwordForm).toBeVisible();
  });

  test('should show error when new passwords do not match', async ({ page }) => {
    // Click on change password section
    await page.getByRole('button', { name: /change password|update password/i }).click();

    // Fill in current password
    await page.getByLabel(/current password|existing password/i).fill(testUser.currentPassword);

    // Fill in new password
    await page.getByLabel(/new password/i).first().fill(testUser.newPassword);

    // Fill in mismatched confirm password
    await page.getByLabel(/confirm password|repeat password/i).fill('DifferentPassword789!');

    // Submit the form
    await page.getByRole('button', { name: /save|update|change password/i }).click();

    // Verify error message about password mismatch
    const errorMessage = page.getByText(/do not match|passwords.*match|confirm.*password/i);
    await expect(errorMessage).toBeVisible();
  });

  test('should validate password requirements', async ({ page }) => {
    // Click on change password section
    await page.getByRole('button', { name: /change password|update password/i }).click();

    // Fill in current password
    await page.getByLabel(/current password|existing password/i).fill(testUser.currentPassword);

    // Fill in weak new password
    await page.getByLabel(/new password/i).first().fill('weak');

    // Fill in confirm password
    await page.getByLabel(/confirm password|repeat password/i).fill('weak');

    // Submit the form
    await page.getByRole('button', { name: /save|update|change password/i }).click();

    // Verify validation error message
    const validationError = page.getByText(/password.*must|requirements|at least|characters|uppercase|number|special/i);
    await expect(validationError).toBeVisible();
  });

  test('should require all fields to be filled before submission', async ({ page }) => {
    // Click on change password section
    await page.getByRole('button', { name: /change password|update password/i }).click();

    // Try to submit without filling any fields
    const submitButton = page.getByRole('button', { name: /save|update|change password/i });

    // Verify submit button is disabled or form shows validation errors
    const currentPasswordField = page.getByLabel(/current password|existing password/i);
    await expect(currentPasswordField).toHaveAttribute('required', '');

    const newPasswordField = page.getByLabel(/new password/i).first();
    await expect(newPasswordField).toHaveAttribute('required', '');

    const confirmPasswordField = page.getByLabel(/confirm password|repeat password/i);
    await expect(confirmPasswordField).toHaveAttribute('required', '');
  });

  test('should allow user to cancel password change', async ({ page }) => {
    // Click on change password section
    await page.getByRole('button', { name: /change password|update password/i }).click();

    // Fill in some data
    await page.getByLabel(/current password|existing password/i).fill(testUser.currentPassword);
    await page.getByLabel(/new password/i).first().fill(testUser.newPassword);

    // Click cancel button
    await page.getByRole('button', { name: /cancel|close|back/i }).click();

    // Verify form is closed or hidden
    const passwordForm = page.getByRole('region', { name: /password/i });
    await expect(passwordForm).not.toBeVisible();
  });
});
